function loadUtils() {
    const authNames = {
        admin: 'admin_auth',
        merchant: 'merchant_auth',
        debtor: 'debtor_auth'
    };
    let utils = {};
    let useToken = function (name) {
        try {
            const data = JSON.parse(pm.collectionVariables.get(name));
            pm.collectionVariables.set("token", data.auth.access_token);
            pm.collectionVariables.set("refresh_token", data.auth.refresh_token);
            pm.collectionVariables.set("current_user", data.email);
            pm.collectionVariables.set("current_auth", data.auth_name);
        }
        catch {
            throw new Error(name + ' is invalid.');
        }
    };
    let saveToken = function (name, data) {
        data.auth_name = name;
        pm.collectionVariables.set(name, JSON.stringify(data));
    };

    utils.useAdminToken = function useAdminToken() {
        console.log('Using admin token');
        useToken(authNames.admin);
    };
    utils.useMerchantToken = function useMerchantToken() {
        console.log('Using merchant token');
        useToken(authNames.merchant);

        const data = JSON.parse(pm.collectionVariables.get(authNames.merchant));
        pm.collectionVariables.set("merchant_user", data.email);
    };
    utils.useWebShopToken = function useWebShopToken() {
        console.log('Using webshop token');
        useToken(authNames.merchant);

        const data = JSON.parse(pm.collectionVariables.get(authNames.merchant));
        pm.collectionVariables.set("token", data.apiKey);
        pm.collectionVariables.set("merchant_user", data.email);
    };
    utils.useDebtorToken = function useDebtorToken() {
        console.log('Using debtor token');
        useToken(authNames.debtor);

        const data = JSON.parse(pm.collectionVariables.get(authNames.debtor));
        pm.collectionVariables.set("debtor_user", data.email);
    };
    utils.saveAdminToken = function setAdminToken(data) {
        console.log('Saved admin token');
        saveToken(authNames.admin, data);
        this.useAdminToken();
    };
    utils.saveMerchantToken = function setMerchantToken(data) {
        console.log('Saved merchant token');
        saveToken(authNames.merchant, data);
        this.useMerchantToken();
    };
    utils.saveDebtorToken = function setDebtorToken(data) {
        console.log('Saved debtor token');
        saveToken(authNames.debtor, data);
        this.useDebtorToken();
    };

    utils.verifyCollectionVariable = function verifyCollectionVariable(name) {
        const value = pm.collectionVariables.get(name);
        if (!value) {
            throw new Error('No value for ' + name + ' variable.');
        }
    };
    return utils;
}; loadUtils();
